pragma solidity 0.6.12;

import "./libraries/ARC20.sol";
import "./libraries/WASA.sol";

// SyrupBar with Governance.
contract SyrupBar is ARC20("SyrupBar Token", "SYRUP") {
    /// @notice Creates `_amount` token to `_to`. Must only be called by the owner (MasterChef).
    function mint(address _to, uint256 _amount) public onlyOwner {
        _mint(_to, _amount);
        _moveDelegates(address(0), _delegates[_to], _amount);
    }

    function burn(address _from, uint256 _amount) public onlyOwner {
        _burn(_from, _amount);
        _moveDelegates(address(0), _delegates[_from], _amount);
    }

    // The WASA TOKEN!
    WASA public wasa;

    constructor(WASA _wasa) public {
        wasa = _wasa;
    }

    receive() external payable {}

    // Safe wasa transfer function, just in case if rounding error causes pool to not have enough WASAs.
    function safeASATransfer(address payable _to, uint256 _amount)
        public
        onlyOwner
    {
        uint256 asaBal = address(this).balance;
        if (_amount > asaBal) {
            _to.transfer(asaBal);
        } else {
            _to.transfer(_amount);
        }
    }

