     */
    function claimBySig(
        address account,
        address token,
        uint256 startEpoch,
        uint256 endEpoch,
        address destination,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external returns (uint256 claimed);

