        for (uint i = 0; i < 5; i++) {
            vm.broadcast(OWNER);
            escrow.fundRepo(repoId, accountId, token1, 500e18, 
                bytes(abi.encodePacked("stress funding round ", i)));
        }

        // Rapid admin additions and removals
        vm.startBroadcast(USER1);
        for (uint i = 0; i < 3; i++) {
            address[] memory newAdmins = new address[](5);
            for (uint j = 0; j < 5; j++) {
