pragma solidity 0.8.28;

/**
 * @title Collection721
 * @author viren tanti
 * @notice Upgradeable ERC-721 collection with signature-based minting and royalty support.
 * @dev Update the `creator` field during initialization; replace the author line with a real name/email.
 */

import "@openzeppelin/contracts-upgradeable/token/ERC721/extensions/ERC721RoyaltyUpgradeable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

import "./libraries/Structs.sol";
import "./interfaces/ICollection721.sol";

contract Collection721 is
    ERC721RoyaltyUpgradeable,
    EIP712Upgradeable,
    ICollection721
{
    using ECDSA for bytes32;
    using Strings for uint256;

    bytes32 public constant MINT_TYPEHASH =
        keccak256("mint(address to,uint256 tokenId)");
    bytes32 public constant BATCHMINT_TYPEHASH =
        keccak256("batchMint(address[] to,uint256[] tokenIds)");
    bytes32 public constant DISABLEMINT_TYPEHASH = keccak256("disableMint()");

    address public creator;
    bool public mintStatus;
    string baseURI_;

    constructor() ERC721Upgradeable() {
        _disableInitializers();
    }

    function initialize(
        Structs.initializeParams721 calldata params
    ) external initializer {
        __ERC721Royalty_init();
        __ERC721_init(params.name, params.symbol);
        _setDefaultRoyalty(params.royaltyContract, params.royaltyFee);
        __EIP712_init(params.name, "1");

        creator = params.creator;
        baseURI_ = params.baseURI;
        mintStatus = true;
        for (uint i; i < params.tokenIds.length; ++i) {
            _safeMint(params.creator, params.tokenIds[i]);
        }
    }

    function supportsInterface(
        bytes4 interfaceId
    ) public view override(ERC721RoyaltyUpgradeable,IERC165) returns (bool) {
        return (super.supportsInterface(interfaceId) ||
            (interfaceId == type(ICollection721).interfaceId) ||
            (interfaceId == type(IERC721).interfaceId));
    }

    function baseURI() internal view virtual returns (string memory) {
        return baseURI_;
    }

    function tokenURI(
        uint256 tokenId
    ) public view override returns (string memory) {
        _requireOwned(tokenId);

        string memory baseuri = baseURI();
        return
            bytes(baseuri).length > 0
                ? string.concat(baseuri, tokenId.toString(), ".json")
                : "";
    }

    function batchMint(
        address[] calldata to,
        uint256[] calldata tokenIds,
        bytes calldata signature
    ) external {
        require(mintStatus, "Minting is disabled");
        require(to.length == tokenIds.length, "length mismatch");

        bytes32 digest = _hashTypedDataV4(_hashBatchMint(to, tokenIds));

        address signer = digest.recover(signature);

        require(signer == creator, "Invalid Signature");

        for (uint i = 0; i < to.length; i++) {
                _safeMint(to[i], tokenIds[i]);

        }
    }

    function mint(
        address to,
        uint256 tokenId,
        bytes calldata signature
    ) external {
        require(mintStatus, "Minting is disabled");

        bytes32 digest = _hashTypedDataV4(_hashMint(to, tokenId));

        address signer = digest.recover(signature);

        require(signer == creator, "Invalid Signature");
        _safeMint(to, tokenId);
    }

    function disableMint(bytes calldata signature) external {
        require(mintStatus == true, "Mint already disabled");

        bytes32 digest = _hashTypedDataV4(_hashDisableMint());
        address signer = digest.recover(signature);

        require(signer == creator, "Invalid Signature");

        mintStatus = false;
    }

    function _feeDenominator() internal pure override returns (uint96) {
        return 100e6;
    }

    function _hashMint(
        address to,
        uint256 tokenId
    ) internal pure returns (bytes32) {
        return keccak256(abi.encode(MINT_TYPEHASH, to, tokenId));
    }

    function _hashDisableMint() internal pure returns (bytes32) {
        return keccak256(abi.encode(DISABLEMINT_TYPEHASH));
    }

    function _hashBatchMint(
        address[] calldata to,
        uint256[] calldata tokenId
    ) internal pure returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    BATCHMINT_TYPEHASH,
                    keccak256(abi.encodePacked(to)),
                    keccak256(abi.encodePacked(tokenId))
                )
            );
    }
}

