pragma solidity ^0.8.24;

import "../interfaces/IERC20.sol";

/// @title OFFToken
/// @notice Governance and utility token for Offshore Cash Protocol
/// @dev ERC20 with permit, vote delegation, and controlled minting
contract OFFToken is IERC20Permit {
    // ═══════════════════════════════════════════════════════════════════════
    // CONSTANTS
    // ═══════════════════════════════════════════════════════════════════════

    string public constant name = "Offshore Cash";
    string public constant symbol = "OFF";
    uint8 public constant decimals = 18;

    /// @notice Maximum supply: 100M tokens
    uint256 public constant MAX_SUPPLY = 100_000_000 * 1e18;

    /// @notice EIP-712 typehash for permit
    bytes32 public constant PERMIT_TYPEHASH = keccak256(
        "Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)"
    );

    /// @notice EIP-712 typehash for delegation
    bytes32 public constant DELEGATION_TYPEHASH = keccak256(
        "Delegation(address delegatee,uint256 nonce,uint256 expiry)"
    );

    // ═══════════════════════════════════════════════════════════════════════
    // STATE
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Total supply
    uint256 public totalSupply;

    /// @notice Token balances
    mapping(address => uint256) public balanceOf;

    /// @notice Allowances
    mapping(address => mapping(address => uint256)) public allowance;

    /// @notice Permit nonces
    mapping(address => uint256) public nonces;

    /// @notice Delegation: delegator => delegatee
    mapping(address => address) public delegates;

    /// @notice Voting checkpoints
    mapping(address => Checkpoint[]) public checkpoints;

    /// @notice Number of checkpoints
    mapping(address => uint256) public numCheckpoints;

    /// @notice Minter role (governance or treasury)
    address public minter;

    /// @notice Owner for initial setup
    address public owner;

    /// @notice Domain separator for EIP-712
    bytes32 public immutable DOMAIN_SEPARATOR;

    // ═══════════════════════════════════════════════════════════════════════
    // STRUCTS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Voting checkpoint
    struct Checkpoint {
        uint32 fromBlock;
        uint224 votes;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════════════

    event DelegateChanged(
        address indexed delegator,
        address indexed fromDelegate,
        address indexed toDelegate
    );

    event DelegateVotesChanged(
        address indexed delegate,
        uint256 previousBalance,
        uint256 newBalance
    );

    event MinterChanged(address indexed oldMinter, address indexed newMinter);
    event OwnerChanged(address indexed oldOwner, address indexed newOwner);

    // ═══════════════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Initialize token
    /// @param _initialSupply Initial supply to mint to deployer
    /// @param _minter Address allowed to mint new tokens
    constructor(uint256 _initialSupply, address _minter) {
        require(_initialSupply <= MAX_SUPPLY, "Exceeds max supply");
        require(_minter != address(0), "Invalid minter");

        owner = msg.sender;
        minter = _minter;

        // Mint initial supply
        if (_initialSupply > 0) {
            _mint(msg.sender, _initialSupply);
        }

        // Compute domain separator
        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes(name)),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ERC20 FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    /// @inheritdoc IERC20
    function transfer(address to, uint256 amount) external override returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    /// @inheritdoc IERC20
    function approve(address spender, uint256 amount) external override returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    /// @inheritdoc IERC20
    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) external override returns (bool) {
        uint256 currentAllowance = allowance[from][msg.sender];
        if (currentAllowance != type(uint256).max) {
            require(currentAllowance >= amount, "Insufficient allowance");
            unchecked {
                _approve(from, msg.sender, currentAllowance - amount);
            }
        }
        _transfer(from, to, amount);
        return true;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // PERMIT
    // ═══════════════════════════════════════════════════════════════════════

    /// @inheritdoc IERC20Permit
    function permit(
        address owner_,
        address spender,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external override {
        require(block.timestamp <= deadline, "Permit expired");

        bytes32 structHash = keccak256(
            abi.encode(
                PERMIT_TYPEHASH,
                owner_,
                spender,
                value,
                nonces[owner_]++,
                deadline
            )
        );

        bytes32 digest = keccak256(
            abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash)
        );

        address recoveredAddress = ecrecover(digest, v, r, s);
        require(recoveredAddress != address(0) && recoveredAddress == owner_, "Invalid signature");

        _approve(owner_, spender, value);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // VOTING & DELEGATION
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Delegate votes to another address
    /// @param delegatee Address to delegate to
    function delegate(address delegatee) external {
        _delegate(msg.sender, delegatee);
    }

    /// @notice Delegate by signature
    /// @param delegatee Address to delegate to
    /// @param nonce Signature nonce
    /// @param expiry Signature expiry
    /// @param v Signature v
    /// @param r Signature r
    /// @param s Signature s
    function delegateBySig(
        address delegatee,
        uint256 nonce,
        uint256 expiry,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        require(block.timestamp <= expiry, "Signature expired");

        bytes32 structHash = keccak256(
            abi.encode(DELEGATION_TYPEHASH, delegatee, nonce, expiry)
        );

        bytes32 digest = keccak256(
            abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash)
        );

        address signatory = ecrecover(digest, v, r, s);
        require(signatory != address(0), "Invalid signature");
        require(nonce == nonces[signatory]++, "Invalid nonce");

        _delegate(signatory, delegatee);
    }

    /// @notice Get current votes for account
    /// @param account Address to check
    /// @return Current vote balance
    function getCurrentVotes(address account) external view returns (uint256) {
        uint256 nCheckpoints = numCheckpoints[account];
        return nCheckpoints > 0 ? checkpoints[account][nCheckpoints - 1].votes : 0;
    }

    /// @notice Get votes at specific block
    /// @param account Address to check
    /// @param blockNumber Block number to check
    /// @return Vote balance at block
    function getPriorVotes(address account, uint256 blockNumber) external view returns (uint256) {
        require(blockNumber < block.number, "Not yet determined");

        uint256 nCheckpoints = numCheckpoints[account];
        if (nCheckpoints == 0) return 0;

        // First check most recent balance
        if (checkpoints[account][nCheckpoints - 1].fromBlock <= blockNumber) {
            return checkpoints[account][nCheckpoints - 1].votes;
        }

        // Next check implicit zero balance
        if (checkpoints[account][0].fromBlock > blockNumber) {
            return 0;
        }

        // Binary search
        uint256 lower = 0;
        uint256 upper = nCheckpoints - 1;
        while (upper > lower) {
            uint256 center = upper - (upper - lower) / 2;
            Checkpoint memory cp = checkpoints[account][center];
            if (cp.fromBlock == blockNumber) {
                return cp.votes;
            } else if (cp.fromBlock < blockNumber) {
                lower = center;
            } else {
                upper = center - 1;
            }
        }
        return checkpoints[account][lower].votes;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // MINTING
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Mint new tokens
    /// @param to Recipient address
    /// @param amount Amount to mint
    function mint(address to, uint256 amount) external {
        require(msg.sender == minter, "Only minter");
        require(totalSupply + amount <= MAX_SUPPLY, "Exceeds max supply");
        _mint(to, amount);
    }

    /// @notice Burn tokens
    /// @param amount Amount to burn
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }

    /// @notice Burn tokens from another address
    /// @param from Address to burn from
    /// @param amount Amount to burn
    function burnFrom(address from, uint256 amount) external {
        uint256 currentAllowance = allowance[from][msg.sender];
        require(currentAllowance >= amount, "Insufficient allowance");
        unchecked {
            _approve(from, msg.sender, currentAllowance - amount);
        }
        _burn(from, amount);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ADMIN
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Change minter address
    /// @param newMinter New minter address
    function setMinter(address newMinter) external {
        require(msg.sender == owner || msg.sender == minter, "Unauthorized");
        require(newMinter != address(0), "Invalid minter");

        emit MinterChanged(minter, newMinter);
        minter = newMinter;
    }

    /// @notice Transfer ownership
    /// @param newOwner New owner address
    function transferOwnership(address newOwner) external {
        require(msg.sender == owner, "Only owner");
        require(newOwner != address(0), "Invalid owner");

        emit OwnerChanged(owner, newOwner);
        owner = newOwner;
    }

    /// @notice Renounce ownership
    function renounceOwnership() external {
        require(msg.sender == owner, "Only owner");
        emit OwnerChanged(owner, address(0));
        owner = address(0);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // INTERNAL
    // ═══════════════════════════════════════════════════════════════════════

    function _transfer(address from, address to, uint256 amount) internal {
        require(from != address(0), "Transfer from zero");
        require(to != address(0), "Transfer to zero");
        require(balanceOf[from] >= amount, "Insufficient balance");

        unchecked {
            balanceOf[from] -= amount;
        }
        balanceOf[to] += amount;

        // Move delegates
        _moveDelegates(delegates[from], delegates[to], amount);

        emit Transfer(from, to, amount);
    }

    function _approve(address owner_, address spender, uint256 amount) internal {
        require(owner_ != address(0), "Approve from zero");
        require(spender != address(0), "Approve to zero");

        allowance[owner_][spender] = amount;
        emit Approval(owner_, spender, amount);
    }

    function _mint(address to, uint256 amount) internal {
        require(to != address(0), "Mint to zero");

        totalSupply += amount;
        balanceOf[to] += amount;

        // Move delegates
        _moveDelegates(address(0), delegates[to], amount);

        emit Transfer(address(0), to, amount);
    }

    function _burn(address from, uint256 amount) internal {
        require(from != address(0), "Burn from zero");
        require(balanceOf[from] >= amount, "Insufficient balance");

        unchecked {
            balanceOf[from] -= amount;
        }
        totalSupply -= amount;

        // Move delegates
        _moveDelegates(delegates[from], address(0), amount);

        emit Transfer(from, address(0), amount);
    }

    function _delegate(address delegator, address delegatee) internal {
        address currentDelegate = delegates[delegator];
        uint256 delegatorBalance = balanceOf[delegator];
        delegates[delegator] = delegatee;

        emit DelegateChanged(delegator, currentDelegate, delegatee);

        _moveDelegates(currentDelegate, delegatee, delegatorBalance);
    }

    function _moveDelegates(
        address srcRep,
        address dstRep,
        uint256 amount
    ) internal {
        if (srcRep != dstRep && amount > 0) {
            if (srcRep != address(0)) {
                uint256 srcRepNum = numCheckpoints[srcRep];
                uint256 srcRepOld = srcRepNum > 0 ? checkpoints[srcRep][srcRepNum - 1].votes : 0;
                uint256 srcRepNew = srcRepOld - amount;
                _writeCheckpoint(srcRep, srcRepNum, srcRepOld, srcRepNew);
            }

            if (dstRep != address(0)) {
                uint256 dstRepNum = numCheckpoints[dstRep];
                uint256 dstRepOld = dstRepNum > 0 ? checkpoints[dstRep][dstRepNum - 1].votes : 0;
                uint256 dstRepNew = dstRepOld + amount;
                _writeCheckpoint(dstRep, dstRepNum, dstRepOld, dstRepNew);
            }
        }
    }

    function _writeCheckpoint(
        address delegatee,
        uint256 nCheckpoints,
        uint256 oldVotes,
        uint256 newVotes
    ) internal {
        if (nCheckpoints > 0 && checkpoints[delegatee][nCheckpoints - 1].fromBlock == block.number) {
            checkpoints[delegatee][nCheckpoints - 1].votes = uint224(newVotes);
        } else {
            checkpoints[delegatee].push(Checkpoint({
                fromBlock: uint32(block.number),
                votes: uint224(newVotes)
            }));
            numCheckpoints[delegatee] = nCheckpoints + 1;
        }

        emit DelegateVotesChanged(delegatee, oldVotes, newVotes);
    }
}

