// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.25;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Address } from "@openzeppelin/contracts/utils/Address.sol";

import { TypeCasts } from "@hyperlane-xyz/libs/TypeCasts.sol";
import { IPermit2, ISignatureTransfer } from "@uniswap/permit2/src/interfaces/IPermit2.sol";

import {
    GaslessCrossChainOrder,
    OnchainCrossChainOrder,
    ResolvedCrossChainOrder,
    IOriginSettler,
    IDestinationSettler
} from "./ERC7683/IERC7683.sol";

/**
 * @title Base7683
 * @notice Implements the ERC7683 standard for cross-chain order resolution, filling, settlement, and refunding.
 * @author BootNode
 * @dev Contains logic for managing orders without requiring specifics of the order data type.
 * Notice that settling and refunding is not described in the ERC7683 but it is included here to provide a common
 * interface for solvers to use.
 */
abstract contract Base7683 is IOriginSettler, IDestinationSettler {
    // ============ Libraries ============
    using SafeERC20 for IERC20;

    // ============ Constants ============
    /// @notice The instance of the Permit2 contract.
    IPermit2 public immutable PERMIT2;

    /// @notice Type hash used for encoding ResolvedCrossChainOrder.
    bytes32 public constant RESOLVED_CROSS_CHAIN_ORDER_TYPEHASH = keccak256(
        "ResolvedCrossChainOrder(address user, uint64 originChainId, uint32 openDeadline, uint32 fillDeadline, Output[] maxSpent, Output[] minReceived, FillInstruction[] fillInstructions)Output(bytes32 token, uint256 amount, bytes32 recipient, uint64 chainId)FillInstruction(uint64 destinationChainId, bytes32 destinationSettler, bytes originData)"
    );

    /// @notice The witness type string used in PERMIT2 transactions.
    string public constant witnessTypeString =
        "ResolvedCrossChainOrder witness)ResolvedCrossChainOrder(address user, uint64 originChainId, uint32 openDeadline, uint32 fillDeadline, Output[] maxSpent, Output[] minReceived, FillInstruction[] fillInstructions)Output(bytes32 token, uint256 amount, bytes32 recipient, uint64 chainId)FillInstruction(uint64 destinationChainId, bytes32 destinationSettler, bytes originData)TokenPermissions(address token,uint256 amount)";

    /// @notice Possible statuses for an order. Other possible statuses should be defined in the inheriting contract.
    bytes32 public constant UNKNOWN = "";
    bytes32 public constant OPENED = "OPENED";
    bytes32 public constant FILLED = "FILLED";

    // ============ Structs ============
    /**
     * @dev Represents data for an order that has been filled.
     * @param originData The origin-specific data for the order.
     * @param fillerData The filler-specific data for the order.
     */
    struct FilledOrder {
        bytes originData;
        bytes fillerData;
    }

    // ============ Public Storage ============

    /// @notice Tracks the used nonces for each address.
    mapping(address => mapping(uint256 => bool)) public usedNonces;

    /// @notice Stores the resolved orders by their ID.
    mapping(bytes32 orderId => bytes orderData) public openOrders;

    /// @notice Tracks filled orders and their associated data.
    mapping(bytes32 orderId => FilledOrder filledOrder) public filledOrders;

    /// @notice Tracks the status of each order by its ID.
    mapping(bytes32 orderId => bytes32 status) public orderStatus;

    // ============ Upgrade Gap ============
    /// @dev Reserved space for future storage variables to ensure upgradeability.
    uint256[47] private __GAP;

    // ============ Events ============
    /**
     * @notice Emitted when an order is filled.
     * @param orderId The ID of the filled order.
     * @param originData The origin-specific data for the order.
     * @param fillerData The filler-specific data for the order.
     */
    event Filled(bytes32 orderId, bytes originData, bytes fillerData);

    /**
     * @notice Emitted when a batch of orders is settled.
     * @param orderIds The IDs of the orders being settled.
     * @param ordersFillerData The filler data for the settled orders.
     */
    event Settle(bytes32[] orderIds, bytes[] ordersFillerData);

    /**
     * @notice Emitted when a batch of orders is refunded.
     * @param orderIds The IDs of the refunded orders.
     */
    event Refund(bytes32[] orderIds);

    /**
     * @notice Emitted when a nonce is invalidated for an address.
     * @param owner The address whose nonce was invalidated.
     * @param nonce The invalidated nonce.
     */
    event NonceInvalidation(address indexed owner, uint256 nonce);

    // ============ Errors ============

    error OrderOpenExpired();
    error InvalidOrderStatus();
    error InvalidGaslessOrderSettler();
    error InvalidGaslessOrderOrigin();
    error InvalidNonce();
    error InvalidOrderOrigin();
    error OrderFillNotExpired();
    error InvalidNativeAmount();

    // ============ Constructor ============
    /**
     * @notice Initializes the contract with the given Permit2 contract address.
     * @param _permit2 The address of the Permit2 contract.
     */
    constructor(address _permit2) {
        PERMIT2 = IPermit2(_permit2);
    }

    // ============ Initializers ============

    // ============ External Functions ============

    /**
     * @notice Opens a gasless cross-chain order on behalf of a user.
     * @dev To be called by the filler.
     * @dev This method must emit the Open event
     * @param _order The GaslessCrossChainOrder definition
     * @param _signature The user's signature over the order
     * @param _originFillerData Any filler-defined data required by the settler
     */
    function openFor(
        GaslessCrossChainOrder calldata _order,
        bytes calldata _signature,
        bytes calldata _originFillerData
    )
        external
        virtual
    {
        if (block.timestamp > _order.openDeadline) revert OrderOpenExpired();
        if (_order.originSettler != address(this)) revert InvalidGaslessOrderSettler();
        if (_order.originChainId != _localDomain()) revert InvalidGaslessOrderOrigin();

        (ResolvedCrossChainOrder memory resolvedOrder, bytes32 orderId, uint256 nonce) = _resolveOrder(_order, _originFillerData);

        openOrders[orderId] = abi.encode(_order.orderDataType, _order.orderData);
        orderStatus[orderId] = OPENED;
        _useNonce(_order.user, nonce);

        _permitTransferFrom(resolvedOrder, _signature, _order.nonce, address(this));

        emit Open(orderId, resolvedOrder);
    }

    /**
     * @notice Opens a cross-chain order
     * @dev To be called by the user
     * @dev This method must emit the Open event
     * @param _order The OnchainCrossChainOrder definition
     */
    function open(OnchainCrossChainOrder calldata _order) external payable virtual {
        (ResolvedCrossChainOrder memory resolvedOrder, bytes32 orderId, uint256 nonce) = _resolveOrder(_order);

        openOrders[orderId] = abi.encode(_order.orderDataType, _order.orderData);
        orderStatus[orderId] = OPENED;
        _useNonce(msg.sender, nonce);

        uint256 totalValue;
        for (uint256 i = 0; i < resolvedOrder.minReceived.length; i++) {
            address token = TypeCasts.bytes32ToAddress(resolvedOrder.minReceived[i].token);
            if (token == address(0)) {
                totalValue += resolvedOrder.minReceived[i].amount;
            } else {
                IERC20(token).safeTransferFrom(msg.sender, address(this), resolvedOrder.minReceived[i].amount);
            }
        }

        if (msg.value != totalValue) revert InvalidNativeAmount();

        emit Open(orderId, resolvedOrder);
    }

    /**
     * @notice Resolves a specific GaslessCrossChainOrder into a generic ResolvedCrossChainOrder
     * @dev Intended to improve standardized integration of various order types and settlement contracts
     * @param _order The GaslessCrossChainOrder definition
     * NOT USED originFillerData Any filler-defined data required by the settler
     * @return _resolvedOrder ResolvedCrossChainOrder hydrated order data including the inputs and outputs of the order
     */
    function resolveFor(
        GaslessCrossChainOrder calldata _order,
        bytes calldata _originFillerData
    )
        public
        view
        virtual
        returns (ResolvedCrossChainOrder memory _resolvedOrder)
    {
        (_resolvedOrder,,) = _resolveOrder(_order, _originFillerData);
    }

    /**
     * @notice Resolves a specific OnchainCrossChainOrder into a generic ResolvedCrossChainOrder
     * @dev Intended to improve standardized integration of various order types and settlement contracts
     * @param _order The OnchainCrossChainOrder definition
     * @return _resolvedOrder ResolvedCrossChainOrder hydrated order data including the inputs and outputs of the order
     */
    function resolve(OnchainCrossChainOrder calldata _order)
        public
        view
        virtual
        returns (ResolvedCrossChainOrder memory _resolvedOrder)
    {
        (_resolvedOrder,,) = _resolveOrder(_order);
    }

    /**
     * @notice Fills a single leg of a particular order on the destination chain
     * @param _orderId Unique order identifier for this order
     * @param _originData Data emitted on the origin to parameterize the fill
     * @param _fillerData Data provided by the filler to inform the fill or express their preferences. It should
     * contain the bytes32 encoded address of the receiver which is used at settlement time
     */
    function fill(bytes32 _orderId, bytes calldata _originData, bytes calldata _fillerData) external payable virtual {
        if (orderStatus[_orderId] != UNKNOWN) revert InvalidOrderStatus();

        _fillOrder(_orderId, _originData, _fillerData);

        orderStatus[_orderId] = FILLED;
        filledOrders[_orderId] = FilledOrder(_originData, _fillerData);

        emit Filled(_orderId, _originData, _fillerData);
    }

    /**
     * @notice Settles a batch of filled orders on the chain where the orders were opened.
     * @dev Pays the filler the amount locked when the orders were opened.
     * The settled status should not be changed here but rather on the origin chain. To allow the filler to retry in
     * case some error occurs.
     * Ensuring the order is eligible for settling in the origin chain is the responsibility of the caller.
     * @param _orderIds An array of IDs for the orders to settle.
     */
    function settle(bytes32[] calldata _orderIds) external payable {
        bytes[] memory ordersOriginData = new bytes[](_orderIds.length);
        bytes[] memory ordersFillerData = new bytes[](_orderIds.length);
        for (uint256 i = 0; i < _orderIds.length; i += 1) {
            // all orders must be FILLED
            if (orderStatus[_orderIds[i]] != FILLED) revert InvalidOrderStatus();

            ordersOriginData[i] = filledOrders[_orderIds[i]].originData;
            ordersFillerData[i] = filledOrders[_orderIds[i]].fillerData;
        }

        _settleOrders(_orderIds, ordersOriginData, ordersFillerData);

        emit Settle(_orderIds, ordersFillerData);
    }

    /**
     * @notice Refunds a batch of expired GaslessCrossChainOrders on the chain where the orders were opened.
     * The refunded status should not be changed here but rather on the origin chain. To allow the user to retry in
     * case some error occurs.
     * Ensuring the order is eligible for refunding in the origin chain is the responsibility of the caller.
     * @param _orders An array of GaslessCrossChainOrders to refund.
     */
    function refund(GaslessCrossChainOrder[] memory _orders) external payable {
        bytes32[] memory orderIds = new bytes32[](_orders.length);
        for (uint256 i = 0; i < _orders.length; i += 1) {
            bytes32 orderId = _getOrderId(_orders[i]);
            orderIds[i] = orderId;

            if (orderStatus[orderId] != UNKNOWN) revert InvalidOrderStatus();
            if (block.timestamp <= _orders[i].fillDeadline) revert OrderFillNotExpired();
        }

        _refundOrders(_orders, orderIds);

        emit Refund(orderIds);
    }

    /**
     * @notice Refunds a batch of expired OnchainCrossChainOrder on the chain where the orders were opened.
     * The refunded status should not be changed here but rather on the origin chain. To allow the user to retry in
     * case some error occurs.
     * Ensuring the order is eligible for refunding the origin chain is the responsibility of the caller.
     * @param _orders An array of GaslessCrossChainOrders to refund.
     */
    function refund(OnchainCrossChainOrder[] memory _orders) external payable {
        bytes32[] memory orderIds = new bytes32[](_orders.length);
        for (uint256 i = 0; i < _orders.length; i += 1) {
            bytes32 orderId = _getOrderId(_orders[i]);
            orderIds[i] = orderId;

            if (orderStatus[orderId] != UNKNOWN) revert InvalidOrderStatus();
            if (block.timestamp <= _orders[i].fillDeadline) revert OrderFillNotExpired();
        }

        _refundOrders(_orders, orderIds);

        emit Refund(orderIds);
    }

    /**
     * @notice Invalidates a nonce for the user calling the function.
     * @param _nonce The nonce to invalidate.
     */
    function invalidateNonces(uint256 _nonce) external virtual {
        _useNonce(msg.sender, _nonce);

        emit NonceInvalidation(msg.sender, _nonce);
    }

    /**
     * @notice Checks whether a given nonce is valid.
     * @param _from The address whose nonce validity is being checked.
     * @param _nonce The nonce to check.
     * @return isValid True if the nonce is valid, false otherwise.
     */
    function isValidNonce(address _from, uint256 _nonce) external view virtual returns (bool) {
        return !usedNonces[_from][_nonce];
    }

    // ============ Public Functions ============

    /**
     * @notice Computes the Permit2 witness hash for a given ResolvedCrossChainOrder.
     * @param _resolvedOrder The ResolvedCrossChainOrder to compute the witness hash for.
     * @return The computed witness hash.
     */
    function witnessHash(ResolvedCrossChainOrder memory _resolvedOrder) public pure virtual returns (bytes32) {
        return keccak256(
            abi.encode(
                RESOLVED_CROSS_CHAIN_ORDER_TYPEHASH,
                _resolvedOrder.user,
                _resolvedOrder.originChainId,
                _resolvedOrder.openDeadline,
                _resolvedOrder.fillDeadline,
                _resolvedOrder.maxSpent,
                _resolvedOrder.minReceived,
                _resolvedOrder.fillInstructions
            )
        );
    }

    // ============ Internal Functions ============

    /**
     * @notice Marks a nonce as used by setting its bit in the appropriate bitmap.
     * @dev Ensures that a nonce cannot be reused by flipping the corresponding bit in the bitmap.
     * Reverts if the nonce is already used.
     * @param _from The address for which the nonce is being used.
     * @param _nonce The nonce to mark as used.
     */
    function _useNonce(address _from, uint256 _nonce) internal {
        if (usedNonces[_from][_nonce]) revert InvalidNonce();
        usedNonces[_from][_nonce] = true;
    }

    /**
     * @notice Executes a batch token transfer using the Permit2 `permitWitnessTransferFrom` method.
     * @dev Transfers tokens specified in a resolved cross-chain order to the receiver.
     * @param _resolvedOrder The resolved order specifying tokens and amounts to transfer.
     * @param _signature The user's signature for the permit.
     * @param _nonce The unique nonce associated with the order.
     * @param _receiver The address that will receive the tokens.
     */
    function _permitTransferFrom(
        ResolvedCrossChainOrder memory _resolvedOrder,
        bytes calldata _signature,
        uint256 _nonce,
        address _receiver
    )
        internal
    {
        ISignatureTransfer.TokenPermissions[] memory permitted =
            new ISignatureTransfer.TokenPermissions[](_resolvedOrder.minReceived.length);

        ISignatureTransfer.SignatureTransferDetails[] memory transferDetails =
            new ISignatureTransfer.SignatureTransferDetails[](_resolvedOrder.minReceived.length);

        for (uint256 i = 0; i < _resolvedOrder.minReceived.length; i++) {
            permitted[i] = ISignatureTransfer.TokenPermissions({
                token: TypeCasts.bytes32ToAddress(_resolvedOrder.minReceived[i].token),
                amount: _resolvedOrder.minReceived[i].amount
            });
            transferDetails[i] = ISignatureTransfer.SignatureTransferDetails({
                to: _receiver,
                requestedAmount: _resolvedOrder.minReceived[i].amount
            });
        }

        ISignatureTransfer.PermitBatchTransferFrom memory permit = ISignatureTransfer.PermitBatchTransferFrom({
            permitted: permitted,
            nonce: _nonce,
            deadline: _resolvedOrder.openDeadline
        });

        PERMIT2.permitWitnessTransferFrom(
            permit, transferDetails, _resolvedOrder.user, witnessHash(_resolvedOrder), witnessTypeString, _signature
        );
    }

    /**
     * @notice Resolves a GaslessCrossChainOrder into a ResolvedCrossChainOrder.
     * @dev To be implemented by the inheriting contract. Contains logic specific to the order type and data.
     * @param _order The GaslessCrossChainOrder to resolve.
     * @param _originFillerData Any filler-defined data required by the settler
     * @return _resolvedOrder A ResolvedCrossChainOrder with hydrated data.
     * @return _orderId The unique identifier for the order.
     * @return _nonce The nonce associated with the order.
     */
    function _resolveOrder(GaslessCrossChainOrder memory _order, bytes calldata _originFillerData)
        internal
        view
        virtual
        returns (ResolvedCrossChainOrder memory _resolvedOrder, bytes32 _orderId, uint256 _nonce);

    /**
     * @notice Resolves an OnchainCrossChainOrder into a ResolvedCrossChainOrder.
     * @dev To be implemented by the inheriting contract. Contains logic specific to the order type and data.
     * @param _order The OnchainCrossChainOrder to resolve.
     * @return _resolvedOrder A ResolvedCrossChainOrder with hydrated data.
     * @return _orderId The unique identifier for the order.
     * @return _nonce The nonce associated with the order.
     */
    function _resolveOrder(OnchainCrossChainOrder memory _order)
        internal
        view
        virtual
        returns (ResolvedCrossChainOrder memory _resolvedOrder, bytes32 _orderId, uint256 _nonce);

    /**
     * @notice Fills an order with specific origin and filler data.
     * @dev To be implemented by the inheriting contract. Defines how to process the origin and filler data.
     * @param _orderId The unique identifier for the order to fill.
     * @param _originData Data emitted on the origin chain to parameterize the fill.
     * @param _fillerData Data provided by the filler, including preferences and additional information.
     */
    function _fillOrder(bytes32 _orderId, bytes calldata _originData, bytes calldata _fillerData) internal virtual;

    /**
     * @notice Settles a batch of orders using their origin and filler data.
     * @dev To be implemented by the inheriting contract. Contains the specific logic for settlement.
     * @param _orderIds An array of order IDs to settle.
     * @param _ordersOriginData The origin data for the orders being settled.
     * @param _ordersFillerData The filler data for the orders being settled.
     */
    function _settleOrders(
        bytes32[] calldata _orderIds,
        bytes[] memory _ordersOriginData,
        bytes[] memory _ordersFillerData
    )
        internal
        virtual;

    /**
     * @notice Refunds a batch of OnchainCrossChainOrders.
     * @dev To be implemented by the inheriting contract. Contains logic specific to refunds.
     * @param _orders An array of OnchainCrossChainOrders to refund.
     * @param _orderIds An array of IDs for the orders to refund.
     */
    function _refundOrders(OnchainCrossChainOrder[] memory _orders, bytes32[] memory _orderIds) internal virtual;

    /**
     * @notice Refunds a batch of GaslessCrossChainOrders.
     * @dev To be implemented by the inheriting contract. Contains logic specific to refunds.
     * @param _orders An array of GaslessCrossChainOrders to refund.
     * @param _orderIds An array of IDs for the orders to refund.
     */
    function _refundOrders(GaslessCrossChainOrder[] memory _orders, bytes32[] memory _orderIds) internal virtual;

    /**
     * @notice Retrieves the local domain identifier.
     * @dev To be implemented by the inheriting contract. Specifies the logic to determine the local domain.
     * @return The local domain ID.
     */
    function _localDomain() internal view virtual returns (uint32);

    /**
     * @notice Computes the unique identifier for a GaslessCrossChainOrder.
     * @dev To be implemented by the inheriting contract. Specifies the logic to compute the order ID.
     * @param _order The GaslessCrossChainOrder to compute the ID for.
     * @return The unique identifier for the order.
     */
    function _getOrderId(GaslessCrossChainOrder memory _order) internal pure virtual returns (bytes32);

    /**
     * @notice Computes the unique identifier for an OnchainCrossChainOrder.
     * @dev To be implemented by the inheriting contract. Specifies the logic to compute the order ID.
     * @param _order The OnchainCrossChainOrder to compute the ID for.
     * @return The unique identifier for the order.
     */
    function _getOrderId(OnchainCrossChainOrder memory _order) internal pure virtual returns (bytes32);
}

airswap/airswap-protocols/source/swap-er:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.23;

import { ECDSA } from "solady/src/utils/ECDSA.sol";
import { EIP712 } from "solady/src/utils/EIP712.sol";
import { ERC20 } from "solady/src/tokens/ERC20.sol";
import { Ownable } from "solady/src/auth/Ownable.sol";
import { SafeTransferLib } from "solady/src/utils/SafeTransferLib.sol";
import { SignatureCheckerLib } from "solady/src/utils/SignatureCheckerLib.sol";

import "./interfaces/ISwapERC20.sol";

/**
 * @title AirSwap: Atomic ERC20 Token Swap
 * @notice https://www.airswap.io/
 */
contract SwapERC20 is ISwapERC20, Ownable, EIP712 {
  bytes32 public immutable DOMAIN_SEPARATOR;

  bytes32 public constant ORDER_TYPEHASH =
    keccak256(
      abi.encodePacked(
        "OrderERC20(uint256 nonce,uint256 expiry,address signerWallet,address signerToken,uint256 signerAmount,",
        "uint256 protocolFee,address senderWallet,address senderToken,uint256 senderAmount)"
      )
    );

  uint256 public constant FEE_DIVISOR = 10000;
  uint256 private constant MAX_ERROR_COUNT = 7;
  uint256 private constant MAX_MAX = 100;
  uint256 private constant MAX_SCALE = 77;

  /**
   * @notice Double mapping of signers to nonce groups to nonce states
   * @dev The nonce group is computed as nonce / 256, so each group of 256 sequential nonces uses the same key
   * @dev The nonce states are encoded as 256 bits, for each nonce in the group 0 means available and 1 means used
   */
  mapping(address => mapping(uint256 => uint256)) private _nonceGroups;

  // Mapping of signer to authorized signatory
  mapping(address => address) public override authorized;

  uint256 public protocolFee;
  uint256 public protocolFeeLight;
  address public protocolFeeWallet;
  uint256 public bonusScale;
  uint256 public bonusMax;
  address public stakingToken;

  /**
   * @notice SwapERC20 constructor
   * @dev Sets domain and version for EIP712 signatures
   * @param _protocolFee uin256 protocol fee to be assessed on swaps
   * @param _protocolFeeWallet address destination for protocol fees
   * @param _bonusScale uin256 scale factor for bonus
   * @param _bonusMax uint256 max bonus percentage
   */
  constructor(
    uint256 _protocolFee,
    uint256 _protocolFeeLight,
    address _protocolFeeWallet,
    uint256 _bonusScale,
    uint256 _bonusMax
  ) {
    if (_protocolFee >= FEE_DIVISOR) revert ProtocolFeeInvalid();
    if (_protocolFeeLight >= FEE_DIVISOR) revert ProtocolFeeLightInvalid();
    if (_protocolFeeWallet == address(0)) revert ProtocolFeeWalletInvalid();
    if (_bonusMax > MAX_MAX) revert MaxTooHigh();
    if (_bonusScale > MAX_SCALE) revert ScaleTooHigh();

    _initializeOwner(msg.sender);

    DOMAIN_SEPARATOR = _domainSeparator();

    protocolFee = _protocolFee;
    protocolFeeLight = _protocolFeeLight;
    protocolFeeWallet = _protocolFeeWallet;
    bonusMax = _bonusMax;
    bonusScale = _bonusScale;
  }

  /**
   * @notice Return EIP712 domain values
   * @return name EIP712 domain name
   * @return version EIP712 domain version
   */
  function _domainNameAndVersion()
    internal
    pure
    override
    returns (string memory name, string memory version)
  {
    name = "SWAP_ERC20";
    version = "4.3";
  }

  /**
   * @notice Atomic ERC20 Swap
   * @param recipient address Wallet to receive sender proceeds
   * @param nonce uint256 Unique and should be sequential
   * @param expiry uint256 Expiry in seconds since 1 January 1970
   * @param signerWallet address Wallet of the signer
   * @param signerToken address ERC20 token transferred from the signer
   * @param signerAmount uint256 Amount transferred from the signer
   * @param senderToken address ERC20 token transferred from the sender
   * @param senderAmount uint256 Amount transferred from the sender
   * @param v uint8 "v" value of the ECDSA signature
   * @param r bytes32 "r" value of the ECDSA signature
   * @param s bytes32 "s" value of the ECDSA signature
   */
  function swap(
    address recipient,
    uint256 nonce,
    uint256 expiry,
    address signerWallet,
    address signerToken,
    uint256 signerAmount,
    address senderToken,
    uint256 senderAmount,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) external override {
    // Ensure the order is valid
    _check(
      nonce,
      expiry,
      signerWallet,
      signerToken,
      signerAmount,
      msg.sender,
      senderToken,
      senderAmount,
      v,
      r,
      s
    );

    // Transfer token from sender to signer
    SafeTransferLib.safeTransferFrom(
      senderToken,
      msg.sender,
      signerWallet,
      senderAmount
    );

    // Transfer token from signer to recipient
    SafeTransferLib.safeTransferFrom(
      signerToken,
      signerWallet,
      recipient,
      signerAmount
    );

    // Calculate and transfer protocol fee
    _transferProtocolFee(signerToken, signerWallet, signerAmount);

    // Emit event
    emit SwapERC20(nonce, signerWallet);
  }

  /**
   * @notice Atomic ERC20 Swap for Any Sender
   * @param recipient address Wallet to receive sender proceeds
   * @param nonce uint256 Unique and should be sequential
   * @param expiry uint256 Expiry in seconds since 1 January 1970
   * @param signerWallet address Wallet of the signer
   * @param signerToken address ERC20 token transferred from the signer
   * @param signerAmount uint256 Amount transferred from the signer
   * @param senderToken address ERC20 token transferred from the sender
   * @param senderAmount uint256 Amount transferred from the sender
   * @param v uint8 "v" value of the ECDSA signature
   * @param r bytes32 "r" value of the ECDSA signature
   * @param s bytes32 "s" value of the ECDSA signature
   */
  function swapAnySender(
    address recipient,
    uint256 nonce,
    uint256 expiry,
    address signerWallet,
    address signerToken,
    uint256 signerAmount,
    address senderToken,
    uint256 senderAmount,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) external override {
    // Ensure the order is valid
    _check(
      nonce,
      expiry,
      signerWallet,
      signerToken,
      signerAmount,
      address(0),
      senderToken,
      senderAmount,
      v,
      r,
      s
    );

    // Transfer token from sender to signer
    SafeTransferLib.safeTransferFrom(
      senderToken,
      msg.sender,
      signerWallet,
      senderAmount
    );

    // Transfer token from signer to recipient
    SafeTransferLib.safeTransferFrom(
      signerToken,
      signerWallet,
      recipient,
      signerAmount
    );

    // Calculate and transfer protocol fee
    _transferProtocolFee(signerToken, signerWallet, signerAmount);

    // Emit event
    emit SwapERC20(nonce, signerWallet);
  }

  /**
   * @notice Swap Atomic ERC20 Swap (Minimal Gas)
   * @dev No transfer checks. Only use with known tokens.
   * @param nonce uint256 Unique and should be sequential
   * @param expiry uint256 Expiry in seconds since 1 January 1970
   * @param signerWallet address Wallet of the signer
   * @param signerToken address ERC20 token transferred from the signer
   * @param signerAmount uint256 Amount transferred from the signer
   * @param senderToken address ERC20 token transferred from the sender
   * @param senderAmount uint256 Amount transferred from the sender
   * @param v uint8 "v" value of the ECDSA signature
   * @param r bytes32 "r" value of the ECDSA signature
   * @param s bytes32 "s" value of the ECDSA signature
   */
  function swapLight(
    uint256 nonce,
    uint256 expiry,
    address signerWallet,
    address signerToken,
    uint256 signerAmount,
    address senderToken,
    uint256 senderAmount,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) external override {
    // Ensure the expiry is not passed
    if (expiry <= block.timestamp) revert OrderExpired();

    // Recover the signatory from the hash and signature
    address signatory = ECDSA.tryRecover(
      _hashTypedData(
        keccak256(
          abi.encode(
            ORDER_TYPEHASH,
            nonce,
            expiry,
            signerWallet,
            signerToken,
            signerAmount,
            protocolFeeLight,
            msg.sender,
            senderToken,
            senderAmount
          )
        )
      ),
      v,
      r,
      s
    );
    // Ensure the signatory is not null
    if (signatory == address(0)) revert SignatureInvalid();

    // Ensure the nonce is not yet used and if not mark it used
    if (!_markNonceAsUsed(signatory, nonce)) revert NonceAlreadyUsed(nonce);

    // Ensure signatory is authorized to sign
    if (authorized[signerWallet] != address(0)) {
      // If one is set by signer wallet, signatory must be authorized
      if (signatory != authorized[signerWallet]) revert SignatureInvalid();
    } else {
      // Otherwise, signatory must be signer wallet
      if (signatory != signerWallet) revert SignatureInvalid();
    }

    // Transfer token from sender to signer
    SafeTransferLib.safeTransferFrom(
      senderToken,
      msg.sender,
      signerWallet,
      senderAmount
    );

    // Transfer token from signer to sender
    SafeTransferLib.safeTransferFrom(
      signerToken,
      signerWallet,
      msg.sender,
      signerAmount
    );

    // Transfer protocol fee from signer to fee wallet
    SafeTransferLib.safeTransferFrom(
      signerToken,
      signerWallet,
      protocolFeeWallet,
      (signerAmount * protocolFeeLight) / FEE_DIVISOR
    );

    // Emit event
    emit SwapERC20(nonce, signerWallet);
  }

  /**
   * @notice Set the protocol fee
   * @param _protocolFee uint256 Value of the fee in basis points
   */
  function setProtocolFee(uint256 _protocolFee) external onlyOwner {
    // Ensure the fee is less than divisor
    if (_protocolFee >= FEE_DIVISOR) revert ProtocolFeeInvalid();
    protocolFee = _protocolFee;
    emit SetProtocolFee(_protocolFee);
  }

  /**
   * @notice Set the light protocol fee
   * @param _protocolFeeLight uint256 Value of the fee in basis points
   */
  function setProtocolFeeLight(uint256 _protocolFeeLight) external onlyOwner {
    // Ensure the fee is less than divisor
    if (_protocolFeeLight >= FEE_DIVISOR) revert ProtocolFeeLightInvalid();
    protocolFeeLight = _protocolFeeLight;
    emit SetProtocolFeeLight(_protocolFeeLight);
  }

  /**
   * @notice Set the protocol fee wallet
   * @param _protocolFeeWallet address Wallet to transfer fee to
   */
  function setProtocolFeeWallet(address _protocolFeeWallet) external onlyOwner {
    // Ensure the new fee wallet is not null
    if (_protocolFeeWallet == address(0)) revert ProtocolFeeWalletInvalid();
    protocolFeeWallet = _protocolFeeWallet;
    emit SetProtocolFeeWallet(_protocolFeeWallet);
  }

  /**
   * @notice Set staking bonus max
   * @dev Only owner
   * @param _bonusMax uint256
   */
  function setBonusMax(uint256 _bonusMax) external onlyOwner {
    if (_bonusMax > MAX_MAX) revert MaxTooHigh();
    bonusMax = _bonusMax;
    emit SetBonusMax(_bonusMax);
  }

  /**
   * @notice Set staking bonus scale
   * @dev Only owner
   * @param _bonusScale uint256
   */
  function setBonusScale(uint256 _bonusScale) external onlyOwner {
    if (_bonusScale > MAX_SCALE) revert ScaleTooHigh();
    bonusScale = _bonusScale;
    emit SetBonusScale(_bonusScale);
  }

  /**
   * @notice Set staking token
   * @param _stakingToken address Token to check balances on
   */
  function setStaking(address _stakingToken) external onlyOwner {
    // Ensure the new staking token is not null
    if (_stakingToken == address(0)) revert StakingInvalid();
    stakingToken = _stakingToken;
    emit SetStaking(_stakingToken);
  }

  /**
   * @notice Authorize a signatory
   * @param signatory address Wallet of the signatory to authorize
   * @dev Emits an Authorize event
   */
  function authorize(address signatory) external override {
    if (signatory == address(0)) revert SignatoryInvalid();
    authorized[msg.sender] = signatory;
    emit Authorize(signatory, msg.sender);
  }

  /**
   * @notice Revoke the signatory
   * @dev Emits a Revoke event
   */
  function revoke() external override {
    address tmp = authorized[msg.sender];
    delete authorized[msg.sender];
    emit Revoke(tmp, msg.sender);
  }

  /**
   * @notice Cancel one or more nonces
   * @dev Cancelled nonces are marked as used
   * @dev Emits a Cancel event
   * @dev Out of gas may occur in arrays of length > 400
   * @param nonces uint256[] List of nonces to cancel
   */
  function cancel(uint256[] calldata nonces) external override {
    for (uint256 i; i < nonces.length; ) {
      uint256 nonce = nonces[i];
      if (_markNonceAsUsed(msg.sender, nonce)) {
        emit Cancel(nonce, msg.sender);
      }
      unchecked {
        ++i;
      }
    }
  }

  /**
   * @notice Checks an order for errors
   * @param senderWallet address Wallet that would send the order
   * @param nonce uint256 Unique and should be sequential
   * @param expiry uint256 Expiry in seconds since 1 January 1970
   * @param signerWallet address Wallet of the signer
   * @param signerToken address ERC20 token transferred from the signer
   * @param signerAmount uint256 Amount transferred from the signer
   * @param senderToken address ERC20 token transferred from the sender
   * @param senderAmount uint256 Amount transferred from the sender
   * @param v uint8 "v" value of the ECDSA signature
   * @param r bytes32 "r" value of the ECDSA signature
   * @param s bytes32 "s" value of the ECDSA signature
   * @return bytes32[] errors
   */
  function check(
    address senderWallet,
    uint256 nonce,
    uint256 expiry,
    address signerWallet,
    address signerToken,
    uint256 signerAmount,
    address senderToken,
    uint256 senderAmount,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) external view returns (bytes32[] memory) {
    bytes32[] memory errors = new bytes32[](MAX_ERROR_COUNT);
    uint256 count;

    OrderERC20 memory order;
    order.nonce = nonce;
    order.expiry = expiry;
    order.signerWallet = signerWallet;
    order.signerToken = signerToken;
    order.signerAmount = signerAmount;
    order.senderToken = senderToken;
    order.senderAmount = senderAmount;
    order.v = v;
    order.r = r;
    order.s = s;
    order.senderWallet = senderWallet;

    // Validate as the authorized signatory if set
    address signatory = order.signerWallet;
    if (authorized[signatory] != address(0)) {
      signatory = authorized[signatory];
    }

    if (
      !SignatureCheckerLib.isValidSignatureNow(
        signatory,
        _getOrderHash(
          order.nonce,
          order.expiry,
          order.signerWallet,
          order.signerToken,
          order.signerAmount,
          order.senderWallet,
          order.senderToken,
          order.senderAmount
        ),
        abi.encodePacked(r, s, v)
      )
    ) {
      errors[count++] = "SignatureInvalid";
    } else if (nonceUsed(signatory, order.nonce)) {
      errors[count++] = "NonceAlreadyUsed";
    }

    if (order.expiry < block.timestamp) {
      errors[count++] = "OrderExpired";
    }

    if (order.senderWallet != address(0)) {
      uint256 senderBalance = ERC20(order.senderToken).balanceOf(
        order.senderWallet
      );

      uint256 senderAllowance = ERC20(order.senderToken).allowance(
        order.senderWallet,
        address(this)
      );

      if (senderAllowance < order.senderAmount) {
        errors[count++] = "SenderAllowanceLow";
      }

      if (senderBalance < order.senderAmount) {
        errors[count++] = "SenderBalanceLow";
      }
    }

    uint256 signerBalance = ERC20(order.signerToken).balanceOf(
      order.signerWallet
    );

    uint256 signerAllowance = ERC20(order.signerToken).allowance(
      order.signerWallet,
      address(this)
    );

    uint256 signerFeeAmount = (order.signerAmount * protocolFee) / FEE_DIVISOR;

    if (signerAllowance < order.signerAmount + signerFeeAmount) {
      errors[count++] = "SignerAllowanceLow";
    }

    if (signerBalance < order.signerAmount + signerFeeAmount) {
      errors[count++] = "SignerBalanceLow";
    }

    // Truncate errors array to actual count
    if (count != errors.length) {
      assembly {
        mstore(errors, count)
      }
    }

    return errors;
  }

  /**
   * @notice Calculates bonus from staking balance
   * @param stakingBalance uint256
   * @param feeAmount uint256
   */
  function calculateBonus(
    uint256 stakingBalance,
    uint256 feeAmount
  ) public view returns (uint256) {
    uint256 divisor = (uint256(10) ** bonusScale) + stakingBalance;
    return (bonusMax * stakingBalance * feeAmount) / divisor / MAX_MAX;
  }

  /**
   * @notice Calculates protocol fee for an account
   * @param wallet address
   * @param amount uint256
   */
  function calculateProtocolFee(
    address wallet,
    uint256 amount
  ) external view override returns (uint256) {
    // Transfer fee from signer to feeWallet
    uint256 feeAmount = (amount * protocolFee) / FEE_DIVISOR;
    if (stakingToken != address(0) && feeAmount > 0) {
      uint256 bonusAmount = calculateBonus(
        ERC20(stakingToken).balanceOf(wallet),
        feeAmount
      );
      return feeAmount - bonusAmount;
    }
    return feeAmount;
  }

  /**
   * @notice Returns true if the nonce has been used
   * @param signer address Address of the signer
   * @param nonce uint256 Nonce being checked
   */
  function nonceUsed(
    address signer,
    uint256 nonce
  ) public view override returns (bool) {
    uint256 groupKey = nonce / 256;
    uint256 indexInGroup = nonce % 256;
    return (_nonceGroups[signer][groupKey] >> indexInGroup) & 1 == 1;
  }

  /**
   * @notice Marks a nonce as used for the given signer
   * @param signer address Address of the signer for which to mark the nonce as used
   * @param nonce uint256 Nonce to be marked as used
   * @return bool True if the nonce was not marked as used already
   */
  function _markNonceAsUsed(
    address signer,
    uint256 nonce
  ) private returns (bool) {
    uint256 groupKey = nonce / 256;
    uint256 indexInGroup = nonce % 256;
    uint256 group = _nonceGroups[signer][groupKey];

    // If it is already used, return false
    if ((group >> indexInGroup) & 1 == 1) {
      return false;
    }

    _nonceGroups[signer][groupKey] = group | (uint256(1) << indexInGroup);

    return true;
  }

  /**
   * @notice Checks order and reverts on error
   * @param nonce uint256 Unique and should be sequential
   * @param expiry uint256 Expiry in seconds since 1 January 1970
   * @param signerWallet address Wallet of the signer
   * @param signerToken address ERC20 token transferred from the signer
   * @param signerAmount uint256 Amount transferred from the signer
   * @param senderToken address ERC20 token transferred from the sender
   * @param senderAmount uint256 Amount transferred from the sender
   * @param v uint8 "v" value of the ECDSA signature
   * @param r bytes32 "r" value of the ECDSA signature
   * @param s bytes32 "s" value of the ECDSA signature
   */
  function _check(
    uint256 nonce,
    uint256 expiry,
    address signerWallet,
    address signerToken,
    uint256 signerAmount,
    address senderWallet,
    address senderToken,
    uint256 senderAmount,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) private {
    // Ensure the expiry is not passed
    if (expiry <= block.timestamp) revert OrderExpired();

    // Validate as the authorized signatory if set
    address signatory = signerWallet;
    if (authorized[signatory] != address(0)) {
      signatory = authorized[signatory];
    }

    // Ensure the signature is correct for the order
    if (
      !SignatureCheckerLib.isValidSignatureNow(
        signatory,
        _getOrderHash(
          nonce,
          expiry,
          signerWallet,
          signerToken,
          signerAmount,
          senderWallet,
          senderToken,
          senderAmount
        ),
        abi.encodePacked(r, s, v)
      )
    ) revert SignatureInvalid();

    // Ensure the nonce is not yet used and if not mark as used
    if (!_markNonceAsUsed(signatory, nonce)) revert NonceAlreadyUsed(nonce);
  }

  /**
   * @notice Hashes order parameters
   * @param nonce uint256
   * @param expiry uint256
   * @param signerWallet address
   * @param signerToken address
   * @param signerAmount uint256
   * @param senderToken address
   * @param senderAmount uint256
   * @return bytes32
   */
  function _getOrderHash(
    uint256 nonce,
    uint256 expiry,
    address signerWallet,
    address signerToken,
    uint256 signerAmount,
    address senderWallet,
    address senderToken,
    uint256 senderAmount
  ) private view returns (bytes32) {
    return
      _hashTypedData(
        keccak256(
          abi.encode(
            ORDER_TYPEHASH,
            nonce,
            expiry,
            signerWallet,
            signerToken,
            signerAmount,
            protocolFee,
            senderWallet,
            senderToken,
            senderAmount
          )
        )
      );
  }

  /**
   * @notice Calculates and transfers protocol fee and staking bonus
   * @param sourceToken address
   * @param sourceWallet address
   * @param amount uint256
   */
  function _transferProtocolFee(
    address sourceToken,
    address sourceWallet,
    uint256 amount
  ) private {
    // Determine protocol fee from amount
    uint256 feeAmount = (amount * protocolFee) / FEE_DIVISOR;
    if (feeAmount > 0) {
      uint256 bonusAmount;
      if (stakingToken != address(0)) {
        // Only check staking bonus if staking token set
        bonusAmount = calculateBonus(
          ERC20(stakingToken).balanceOf(msg.sender),
          feeAmount
        );
      }
      if (bonusAmount > 0) {
        // Transfer staking bonus from source to msg.sender
        SafeTransferLib.safeTransferFrom(
          sourceToken,
          sourceWallet,
          msg.sender,
          bonusAmount
        );
        // Transfer remaining protocol fee from source to fee wallet
        SafeTransferLib.safeTransferFrom(
          sourceToken,
          sourceWallet,
          protocolFeeWallet,
          feeAmount - bonusAmount
        );
      } else {
        // Transfer full protocol fee from source to fee wallet
        SafeTransferLib.safeTransferFrom(
          sourceToken,
          sourceWallet,
          protocolFeeWallet,
          feeAmount
        );
      }
    }
  }
}

pendle-finance/pendle-core-v2-public/con:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.17;

import "../core/libraries/BoringOwnableUpgradeableV2.sol";
import "../core/libraries/TokenHelper.sol";
import "../interfaces/IPAllActionV3.sol";
import "../interfaces/IPLimitRouter.sol";
import "../interfaces/IStandardizedYield.sol";
import {LimitMathCore as LimitMath} from "./LimitMathCore.sol";
import "./helpers/MintSyHelper.sol";
import "./helpers/NonceManager.sol";
import "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";

abstract contract LimitRouterBase is
    IPLimitRouter,
    MintSyHelper,
    BoringOwnableUpgradeableV2,
    NonceManager,
    TokenHelper
{
    using SafeERC20 for IERC20;
    using PMath for uint256;

    bytes32 internal constant LIMIT_ORDER_TYPEHASH = keccak256(
        "Order(uint256 salt,uint256 expiry,uint256 nonce,uint8 orderType,address token,address YT,address maker,address receiver,uint256 makingAmount,uint256 lnImpliedRate,uint256 failSafeRate,bytes permit)"
    );

    uint128 internal constant _ORDER_DOES_NOT_EXIST = 0;
    uint128 internal constant _ORDER_FILLED = 1;
    uint256 internal constant MAX_LN_FEE_RATE_ROOT = 48_790_164_169_432_003; // ln(1.05)

    address public feeRecipient;

    // YT => lnFeeRateRoot // not to be accessed directly
    mapping(address => uint256) internal __lnFeeRateRoot;

    address public immutable WNATIVE;
    address public immutable ROUTER;

    mapping(bytes32 => OrderStatus) internal _status;

    address private __deprecated__ownerHelper;

    address public mintSySigner1;
    address public mintSySigner2;

    uint256[97] private __gap;

    constructor(address _WNATIVE, address _ROUTER) {
        WNATIVE = _WNATIVE;
        ROUTER = _ROUTER;
    }

    // solhint-disable-next-line no-empty-blocks
    receive() external payable {}

    function initialize(address _feeRecipient, address _owner) external initializer {
        __BoringOwnableV2_init(msg.sender);
        __EIP712_init("Pendle Limit Order Protocol", "1");
        setFeeRecipient(_feeRecipient);
        transferOwnership(_owner, true, false);
    }

    function fill(
        FillOrderParams[] memory params,
        address receiver,
        uint256 maxTaking,
        bytes memory optData,
        bytes memory callback
    ) external returns (uint256 actualMaking, uint256 actualTaking, uint256 totalFee, bytes memory callbackReturn) {
        OptionalArgs memory oArgs = _decodeAndVerifySigOpt_prePrune(params, optData);

        _validateSkipSigAndPruneOrders(params);
        if (params.length == 0) return fillNoOrders(callback);

        OrderType orderType = params[0].order.orderType;
        Args memory a = Args(orderType, params, receiver, maxTaking, callback, oArgs);
        if (orderType == OrderType.SY_FOR_PT || orderType == OrderType.SY_FOR_YT) {
            return fillTokenForPY(a);
        } else {
            return fillPYForToken(a);
        }
    }

    // ----------------- Core logic -----------------

    struct Args {
        OrderType orderType;
        FillOrderParams[] params;
        address receiver;
        uint256 maxTaking;
        bytes callback;
        OptionalArgs oArgs;
    }

    struct OptionalArgs {
        MintSyData mintSyData;
    }

    function fillNoOrders(bytes memory callback)
        internal
        returns (uint256 actualMaking, uint256 actualTaking, uint256 totalFee, bytes memory callbackReturn)
    {
        callbackReturn = callbackIfNeeded(0, 0, 0, callback);
        return (0, 0, 0, callbackReturn);
    }

    function fillTokenForPY(Args memory a)
        internal
        returns (uint256 actualMaking, uint256 actualTaking, uint256 totalFee, bytes memory callbackReturn)
    {
        (address SY, address PT, address YT, bytes32[] memory orderHashes) = _checkSig_updMakingAndStatus(a.params);

        // Token => This
        uint256[] memory fromMakers = _transferFromMakers_mintSy_updMakings(SY, a.params, a.oArgs.mintSyData);

        FillResults memory out = LimitMath.calcBatch(a.params, YT, getLnFeeRateRoot(YT));
        (actualMaking, actualTaking, totalFee) = (out.totalMaking - out.totalFee, out.totalTaking, out.totalFee);

        require(actualTaking <= a.maxTaking, "LOP: maxTaking exceeded");

        // This => Taker
        _transferOut(SY, a.receiver, actualMaking);

        // callback to Taker
        callbackReturn = callbackIfNeeded(actualMaking, actualTaking, totalFee, a.callback);

        // Taker => Makers
        address pyToMaker = (a.orderType == OrderType.SY_FOR_PT) ? PT : YT;
        _transferToMakers(IERC20(pyToMaker), msg.sender, a.params, out.netTakings);

        // This => Fee
        _transferOut(SY, feeRecipient, totalFee);

        // toMakers == netTakings
        _emitEvents(a.params, orderHashes, fromMakers, out.netTakings, out.netFees, out.notionalVolumes);
    }

    function fillPYForToken(Args memory a)
        internal
        returns (uint256 actualMaking, uint256 actualTaking, uint256 totalFee, bytes memory callbackReturn)
    {
        (address SY, address PT, address YT, bytes32[] memory orderHashes) = _checkSig_updMakingAndStatus(a.params);

        FillResults memory out = LimitMath.calcBatch(a.params, YT, getLnFeeRateRoot(YT));
        (actualMaking, actualTaking, totalFee) = (out.totalMaking, out.totalTaking + out.totalFee, out.totalFee);

        require(actualTaking <= a.maxTaking, "LOP: maxTaking exceeded");

        // Makers => Taker
        address pyFromMaker = (a.orderType == OrderType.PT_FOR_SY) ? PT : YT;
        _transferFromMakers(IERC20(pyFromMaker), a.params, a.receiver, out.netMakings);

        // callback to Taker
        callbackReturn = callbackIfNeeded(actualMaking, actualTaking, totalFee, a.callback);

        // Taker => This
        _transferFrom(IERC20(SY), msg.sender, address(this), actualTaking);

        // This => Makers
        uint256[] memory toMakers = _redeemSy_transferToMakers(SY, a.params, out.netTakings);

        // This => Fee
        _transferOut(SY, feeRecipient, totalFee);

        // fromMakers == netMakings
        _emitEvents(a.params, orderHashes, out.netMakings, toMakers, out.netFees, out.notionalVolumes);
    }

    // ----------------- verify & convert functions -----------------

    function _decodeAndVerifySigOpt_prePrune(FillOrderParams[] memory params, bytes memory optData)
        internal
        view
        returns (OptionalArgs memory oArgs)
    {
        if (optData.length != 0) {
            (uint256 version, bytes memory payload) = abi.decode(optData, (uint256, bytes));
            require(version == 1, "LOP: invalid version");

            oArgs.mintSyData = abi.decode(payload, (MintSyData));
            _verifyMintSyData(oArgs.mintSyData, hashFillParams(params), mintSySigner1, mintSySigner2);
        }
    }

    function _validateSkipSigAndPruneOrders(FillOrderParams[] memory params) internal view {
        uint256 len = params.length;
        require(len != 0, "LOP: empty batch");

        (address YT, OrderType orderType) = (params[0].order.YT, params[0].order.orderType);
        require(block.timestamp < IPYieldToken(YT).expiry(), "LOP: PY expired");

        uint256 keep = 0;
        for (uint256 i = 0; i < len; i++) {
            Order memory order = params[i].order;

            require(i == 0 || order.token >= params[i - 1].order.token, "LOP: invalid ordering");
            require(order.orderType == orderType && order.YT == YT, "LOP: mismatch types");

            if (!(block.timestamp < order.expiry && order.nonce >= nonce[order.maker])) continue;

            params[keep] = params[i];
            keep++;
        }

        assembly ("memory-safe") {
            mstore(params, keep)
        }
    }

    function _checkSig_updMakingAndStatus(FillOrderParams[] memory params)
        internal
        returns (address SY, address PT, address YT, bytes32[] memory orderHashes)
    {
        uint256 len = params.length;
        orderHashes = new bytes32[](len);

        for (uint256 i = 0; i < len; i++) {
            FillOrderParams memory param = params[i];

            (bytes32 orderHash, uint256 remainingMakerAmount, uint256 filledMakerAmount) =
                _checkSig(param.order, param.signature);
            uint256 netMaking = PMath.min(param.makingAmount, remainingMakerAmount);

            unchecked {
                remainingMakerAmount = remainingMakerAmount - netMaking;
                _status[orderHash] = OrderStatus({
                    remaining: (remainingMakerAmount + 1).Uint128(),
                    filledAmount: (filledMakerAmount + netMaking).Uint128()
                });
            }

            param.makingAmount = netMaking;

            orderHashes[i] = orderHash;
        }

        YT = params[0].order.YT;
        SY = IPYieldToken(YT).SY();
        PT = IPYieldToken(YT).PT();
    }

    function _emitEvents(
        FillOrderParams[] memory params,
        bytes32[] memory hashes,
        uint256[] memory fromMakers,
        uint256[] memory toMakers,
        uint256[] memory netFees,
        uint256[] memory notionalVolumes
    ) internal {
        uint256 len = hashes.length;

        for (uint256 i = 0; i < len; i++) {
            Order memory order = params[i].order;
            emit OrderFilledV2(
                hashes[i],
                order.orderType,
                order.YT,
                order.token,
                fromMakers[i],
                toMakers[i],
                netFees[i],
                notionalVolumes[i],
                params[i].order.maker,
                msg.sender
            );
        }
    }

    function callbackIfNeeded(uint256 actualMaking, uint256 actualTaking, uint256 totalFee, bytes memory callback)
        internal
        returns (bytes memory callbackReturn)
    {
        if (callback.length > 0) {
            callbackReturn =
                IPLimitRouterCallback(msg.sender).limitRouterCallback(actualMaking, actualTaking, totalFee, callback);
        }
    }

    function _checkSig(Order memory order, bytes memory signature)
        public
        view
        returns (
            bytes32,
            /*orderHash*/
            uint256,
            /*remainingMakerAmount*/
            uint256 /*filledMakerAmount*/
        )
    {
        bytes32 orderHash = hashOrder(order);
        OrderStatus memory status = _status[orderHash];
        (uint256 remainingMakerAmount, uint256 filledMakerAmount) = (status.remaining, status.filledAmount);

        if (remainingMakerAmount == _ORDER_DOES_NOT_EXIST) {
            require(SignatureChecker.isValidSignatureNow(order.maker, orderHash, signature), "LOP: bad signature");

            remainingMakerAmount = order.makingAmount;
        } else {
            unchecked {
                remainingMakerAmount -= 1;
            }
        }

        return (orderHash, remainingMakerAmount, filledMakerAmount);
    }

    // ----------------- simple helper functions -----------------

    function _transferFromMakers_mintSy_updMakings(
        address SY,
        FillOrderParams[] memory params,
        MintSyData memory mintSyData
    ) internal returns (uint256[] memory fromMakers) {
        uint256 len = params.length;
        fromMakers = new uint256[](len);

        for ((uint256 l, uint256 r) = (0, 0); l < len; l = r) {
            address sharedToken = params[l].order.token;
            uint256 totalMaking = 0;
            for (; r < len && params[r].order.token == sharedToken; r++) {
                _transferIn(sharedToken, params[r].order.maker, params[r].makingAmount);
                totalMaking += params[r].makingAmount;
                fromMakers[r] = params[r].makingAmount;
            }

            if (sharedToken == SY || totalMaking == 0) continue;

            uint256 totalSy = __mintSy_Single(SY, sharedToken, totalMaking, mintSyData.inps, mintSyData.minSyOuts);
            for (uint256 i = l; i < r; i++) {
                uint256 netToken = params[i].makingAmount;
                uint256 netSy = (netToken * totalSy) / totalMaking;
                require(netToken.mulDown(params[i].order.failSafeRate) <= netSy, "LOP: fail safe");

                params[i].makingAmount = netSy;
            }
        }
    }

    /// @dev each token group appears at most once because params are sorted by token
    function __mintSy_Single(
        address SY,
        address token,
        uint256 netTokenIn,
        TokenInput[] memory inps,
        uint256[] memory minSyOuts
    ) private returns (uint256 netSyOut) {
        for (uint256 i = 0; i < inps.length; i++) {
            if (inps[i].tokenIn == token) {
                return __mintSy_Single_viaRouter(SY, token, netTokenIn, inps[i], minSyOuts[i]);
            }
        }
        return __mintSy_Single_direct(SY, token, netTokenIn);
    }

    function __mintSy_Single_viaRouter(
        address SY,
        address token,
        uint256 netTokenIn,
        TokenInput memory inp,
        uint256 minSyOut
    ) private returns (uint256 netSyOut) {
        require(inp.swapData.needScale, "LOP: need scale");
        require(netTokenIn <= inp.netTokenIn, "LOP: only scale down");

        // Scale down input
        uint256 scaledMinSyOut = (minSyOut * netTokenIn) / inp.netTokenIn;
        require(scaledMinSyOut > 0, "LOP: zero scaledMinSy");
        inp.netTokenIn = netTokenIn;

        // Approve and mint via router
        _safeApproveInf(token, ROUTER);
        netSyOut = IPAllActionV3(ROUTER).mintSyFromToken(address(this), SY, scaledMinSyOut, inp);
    }

    function __mintSy_Single_direct(address SY, address token, uint256 netTokenIn) private returns (uint256 netSyOut) {
        if (token == WNATIVE && !IStandardizedYield(SY).isValidTokenIn(WNATIVE)) {
            _wrap_unwrap_ETH(WNATIVE, NATIVE, netTokenIn);
            token = NATIVE;
        }
        _safeApproveInf(token, SY);
        return
            IStandardizedYield(SY).deposit{value: token == NATIVE ? netTokenIn : 0}(address(this), token, netTokenIn, 0);
    }

    function _redeemSy_transferToMakers(address SY, FillOrderParams[] memory params, uint256[] memory netSyOuts)
        internal
        returns (uint256[] memory toMakers)
    {
        uint256 len = params.length;
        toMakers = new uint256[](len);

        for ((uint256 l, uint256 r) = (0, 0); l < len; l = r) {
            address sharedToken = params[l].order.token;
            uint256 totalSy = 0;

            for (; r < len && __stillShared(sharedToken, params[r].order.token); r++) {
                totalSy += netSyOuts[r];
            }

            if (totalSy == 0) continue;

            if (sharedToken == SY) {
                for (uint256 i = l; i < r; i++) {
                    _transferOut(SY, params[i].order.receiver, netSyOuts[i]);
                    toMakers[i] = netSyOuts[i];
                }
                continue;
            }

            if (r - l == 1) {
                toMakers[l] = __redeemSy_Single(params[l].order.receiver, SY, sharedToken, netSyOuts[l]);
            } else {
                uint256 totalToken = __redeemSy_Single(address(this), SY, sharedToken, totalSy);
                for (uint256 i = l; i < r; i++) {
                    address token = params[i].order.token;
                    toMakers[i] = (netSyOuts[i] * totalToken) / totalSy;
                    if (sharedToken != token) {
                        // WNATIVE case
                        _wrap_unwrap_ETH(sharedToken, token, toMakers[i]);
                    }
                    _transferOut(token, params[i].order.receiver, toMakers[i]);
                }
            }

            for (uint256 i = l; i < r; i++) {
                uint256 netSy = netSyOuts[i];
                uint256 netToken = toMakers[i];
                require(netSy.mulDown(params[i].order.failSafeRate) <= netToken, "LOP: fail safe");
            }
        }
    }

    function __stillShared(address currentShared, address nextToken) private view returns (bool) {
        return (currentShared == nextToken) || (currentShared == NATIVE && nextToken == WNATIVE)
            || (currentShared == WNATIVE && nextToken == NATIVE);
    }

    function __redeemSy_Single(address receiver, address SY, address tokenOut, uint256 netSyIn)
        private
        returns (uint256 netTokenOut)
    {
        if (tokenOut == NATIVE || tokenOut == WNATIVE) {
            address otherToken = tokenOut == NATIVE ? WNATIVE : NATIVE;
            address tokenRedeemSy = IStandardizedYield(SY).isValidTokenOut(tokenOut) ? tokenOut : otherToken;

            netTokenOut = IStandardizedYield(SY).redeem(address(this), netSyIn, tokenRedeemSy, 0, false);

            if (tokenOut != tokenRedeemSy) {
                _wrap_unwrap_ETH(tokenRedeemSy, tokenOut, netTokenOut);
            }

            if (receiver != address(this)) {
                _transferOut(tokenOut, receiver, netTokenOut);
            }
        } else {
            return IStandardizedYield(SY).redeem(receiver, netSyIn, tokenOut, 0, false);
        }
    }

    // ! Allow self-fill of orders
    function _transferFromMakers(IERC20 token, FillOrderParams[] memory params, address to, uint256[] memory netIn)
        internal
    {
        uint256 len = params.length;
        for (uint256 i = 0; i < len; i++) {
            if (params[i].order.maker == to) continue;
            token.safeTransferFrom(params[i].order.maker, to, netIn[i]);
        }
    }

    function _transferToMakers(IERC20 token, address payer, FillOrderParams[] memory params, uint256[] memory netOut)
        internal
    {
        uint256 len = params.length;
        for (uint256 i = 0; i < len; i++) {
            if (payer == params[i].order.receiver) continue;
            token.safeTransferFrom(payer, params[i].order.receiver, netOut[i]);
        }
    }

    function hashFillParams(FillOrderParams[] memory params) public pure returns (bytes32) {
        return keccak256(abi.encode(params));
    }

    function hashOrder(Order memory order) public view returns (bytes32) {
        StaticOrder memory staticOrder;
        assembly {
            staticOrder := order
        }
        return _hashTypedDataV4(keccak256(abi.encode(LIMIT_ORDER_TYPEHASH, staticOrder, keccak256(order.permit))));
    }

    function getLnFeeRateRoot(address YT) public view returns (uint256 res) {
        res = __lnFeeRateRoot[YT];
        require(res > 0, "LOP: fee not set");
    }

    // ----------------- Owner -----------------

    function setFeeRecipient(address _feeRecipient) public onlyOwner {
        feeRecipient = _feeRecipient;
    }

    function setMintSySigners(address _signer1, address _signer2) public onlyOwner {
        mintSySigner1 = _signer1;
        mintSySigner2 = _signer2;
        emit MintSySignersSet(_signer1, _signer2);
    }

    /// @dev if zero fees are intended, it must be explicitly allowed again
    function setLnFeeRateRoots(address[] memory YTs, uint256[] memory lnFeeRateRoots, bool allowZeroFees)
        public
        onlyOwner
    {
        uint256 len = YTs.length;
        require(len == lnFeeRateRoots.length, "LOP: length mismatch");

        for (uint256 i = 0; i < len; i++) {
            require(lnFeeRateRoots[i] > 0 || allowZeroFees, "LOP: zero fee must be allowed explicitly");
            require(lnFeeRateRoots[i] <= MAX_LN_FEE_RATE_ROOT, "LOP: fee too high");

            __lnFeeRateRoot[YTs[i]] = lnFeeRateRoots[i];
        }

        emit LnFeeRateRootsSet(YTs, lnFeeRateRoots);
    }
}

