pragma solidity ^0.8.13;
// SPDX-License-Identifier: MIT


struct EIP712Domain {
  string name;
  string version;
  uint256 chainId;
  address verifyingContract;
}

bytes32 constant EIP712DOMAIN_TYPEHASH = keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

struct Bid {
  string item;
  TokenVector offer;
}

bytes32 constant BID_TYPEHASH = keccak256("Bid(string item,TokenVector offer)TokenVector(address token,uint256 amount)");

struct TokenVector {
  address token;
  uint256 amount;
}

bytes32 constant TOKENVECTOR_TYPEHASH = keccak256("TokenVector(address token,uint256 amount)");


contract EIP712Decoder {

  /**
  * @dev Recover signer address from a message by using their signature
  * @param hash bytes32 message, the hash is the signed message. What is recovered is the signer address.
  * @param sig bytes signature, the signature is generated using web3.eth.sign()
  */
  function recover(bytes32 hash, bytes memory sig) internal pure returns (address) {
    bytes32 r;
    bytes32 s;
    uint8 v;

    //Check the signature length
    if (sig.length != 65) {
      return (address(0));
    }

    // Divide the signature in r, s and v variables
    assembly {
      r := mload(add(sig, 32))
      s := mload(add(sig, 64))
      v := byte(0, mload(add(sig, 96)))
    }
// Version of signature should be 27 or 28, but 0 and 1 are also possible versions
    if (v < 27) {
      v += 27;
    }

    // If the version is correct return the signer address
    if (v != 27 && v != 28) {
      return (address(0));
    } else {
      return ecrecover(hash, v, r, s);
    }
  }

  function GET_EIP712DOMAIN_PACKETHASH (EIP712Domain memory _input) public pure returns (bytes32) {

    bytes memory encoded = abi.encode(
      EIP712DOMAIN_TYPEHASH,
      _input.name,
      _input.version,
      _input.chainId,
      _input.verifyingContract
    );

    return keccak256(encoded);
  }

  function GET_BID_PACKETHASH (Bid memory _input) public pure returns (bytes32) {

    bytes memory encoded = abi.encode(
      BID_TYPEHASH,
      _input.item,
      GET_TOKENVECTOR_PACKETHASH(_input.offer)
    );

    return keccak256(encoded);
  }

  function GET_TOKENVECTOR_PACKETHASH (TokenVector memory _input) public pure returns (bytes32) {

    bytes memory encoded = abi.encode(
      TOKENVECTOR_TYPEHASH,
      _input.token,
      _input.amount
    );

    return keccak256(encoded);
  }

}


