        IERC721 nft_,
        uint256 items_,
        IERC20Upgradeable weth_,
        address beneficiary_,
        address operator_
    ) external initializer {
        __Ownable_init();
        _erc712DomainInit('$CAR Auction', '1');

        nft = nft_;
        items = items_;
        weth = weth_;
