pragma solidity ^0.8.20;

contract Auction {
    address public owner;
    uint256 public highestBid;
    address public highestBidder;
    mapping(address => bool) public hasSigned;
    bytes32 private constant DOMAIN_SEPARATOR_TYPEHASH = keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 private constant BID_TYPEHASH = keccak256("Bid(address bidder,uint256 amount,uint256 nonce)");
    string private constant NAME = "Auction";
    string private constant VERSION = "1.0.0";

    constructor(uint256 _initialHighestBid) {
        owner = msg.sender;
        highestBid = _initialHighestBid;
    }

    function domainSeparator() internal view returns (bytes32) {
        return keccak256(abi.encode(
            DOMAIN_SEPARATOR_TYPEHASH,
            keccak256(bytes(NAME)),
            keccak256(bytes(VERSION)),
            block.chainid,
            address(this)
        ));
    }

    function getTypedDataHash(address bidder, uint256 amount, uint256 nonce) internal view returns (bytes32) {
        return keccak256(abi.encodePacked(
            '\x19\x01',
            domainSeparator(),
            keccak256(abi.encode(BID_TYPEHASH, bidder, amount, nonce))
        ));
    }

    function submitBid(uint256 amount, uint256 nonce, bytes memory signature) external {
        require(amount > highestBid, "Bid amount must be higher than the current highest bid");
        bytes32 messageHash = getTypedDataHash(msg.sender, amount, nonce);
        require(!hasSigned[msg.sender], "Bidder has already signed");

        address signer = recoverSigner(messageHash, signature);
        require(signer == msg.sender, "Invalid signature");

        highestBid = amount;
        highestBidder = msg.sender;
        hasSigned[msg.sender] = true;
    }

    function recoverSigner(bytes32 messageHash, bytes memory signature) internal pure returns (address) {
        require(signature.length == 65, "Invalid signature length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(signature, 32))
            s := mload(add(signature, 64))
            v := byte(0, mload(add(signature, 96)))
        }
        if (v < 27) {
            v += 27;
        }
        require(v == 27 || v == 28, "Invalid signature v value");
        return ecrecover(messageHash, v, r, s);
    }
}

