// SPDX-License-Identifier: GPL-3.0-or-later

pragma solidity =0.8.4;

//solhint-disable not-rely-on-time
//solhint-disable var-name-mixedcase
//solhint-disable reason-string

import "./interfaces/ISecureFactory.sol";
import "./libraries/TransferHelper.sol";

import "./interfaces/ISecureRouter.sol";
import "./libraries/SecureLibrary.sol";
import "./interfaces/IERC20.sol";
import "./interfaces/IWETH.sol";

contract SecureRouter is ISecureRouter {
    address public immutable override factory;
    address public immutable override WETH;

    address public owner;

    bytes32 public immutable DOMAIN_SEPARATOR;
    mapping(address => uint256) public nonces;

    mapping(address => bool) public authorizedSigners;

    // keccak256("Swap(address caller,uint256 amountIn,uint256 amountOut,uint256[] paths,uint256 nonce,uint256 startline,uint256 deadline)");
    bytes32 public constant SWAP_TYPEHASH =
        0xb4adfbac3cb08c3c789df3219d832799bb62fa32be119e5539c01f0ee8885ce9;

    error RouterOnlyOwner();
    error RouterExpired();
    error RouterOutOfTime();
    error RouterZeroAddress();
    error RouterInsufficientOutputAmount();
    error RouterInsufficientAAmount();
    error RouterInsufficientBAmount();
    error RouterExcessiveInputAmount();
    error RouterInvalidPath();
    error RouterInvalidSigner();
    error RouterInvalidSignatureLength();

    constructor(address _factory, address _WETH) {
        factory = _factory;
        WETH = _WETH;

        owner = msg.sender;

        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256(bytes("Secure Router")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    receive() external payable {
        assert(msg.sender == WETH); // only accept ETH via fallback from the WETH contract
    }

    modifier ensure(uint256 deadline) {
        if (deadline < block.timestamp) {
            revert RouterExpired();
        }
        _;
    }

    modifier ensureSwap(uint256 startline, uint256 deadline) {
        if (block.timestamp < startline || deadline < block.timestamp) {
            revert RouterOutOfTime();
        }
        _;
    }

    modifier onlyOwner() {
        if (msg.sender != owner) {
            revert RouterOnlyOwner();
        }
        _;
    }

    function setSigner(address signer, bool authorized) external onlyOwner {
        authorizedSigners[signer] = authorized;
    }

    function setOwner(address newOwner) external onlyOwner {
        if (newOwner == address(0)) {
            revert RouterZeroAddress();
        }
        owner = newOwner;
    }

    // **** ADD LIQUIDITY ****
    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    )
        external
        virtual
        override
        ensure(deadline)
        returns (uint256 amountA, uint256 amountB, uint256 liquidity)
    {
        (amountA, amountB) = _addLiquidity(
            tokenA,
            tokenB,
            amountADesired,
            amountBDesired,
            amountAMin,
            amountBMin
        );
        address pair = SecureLibrary.pairFor(factory, tokenA, tokenB);
        TransferHelper.safeTransferFrom(tokenA, msg.sender, pair, amountA);
        TransferHelper.safeTransferFrom(tokenB, msg.sender, pair, amountB);
        liquidity = ISecurePair(pair).mint(to);
    }

    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    )
        external
        payable
        virtual
        override
        ensure(deadline)
        returns (uint256 amountToken, uint256 amountETH, uint256 liquidity)
    {
        (amountToken, amountETH) = _addLiquidity(
            token,
            WETH,
            amountTokenDesired,
            msg.value,
            amountTokenMin,
            amountETHMin
        );
        address pair = SecureLibrary.pairFor(factory, token, WETH);
        TransferHelper.safeTransferFrom(token, msg.sender, pair, amountToken);
        IWETH(WETH).deposit{value: amountETH}();
        assert(IWETH(WETH).transfer(pair, amountETH));
        liquidity = ISecurePair(pair).mint(to);
        // refund dust eth, if any
        if (msg.value > amountETH)
            TransferHelper.safeTransferETH(msg.sender, msg.value - amountETH);
    }

    function removeLiquidityWithPermit(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external virtual override returns (uint256 amountA, uint256 amountB) {
        address pair = SecureLibrary.pairFor(factory, tokenA, tokenB);
        uint256 value = approveMax ? type(uint256).max : liquidity;
        ISecurePair(pair).permit(
            msg.sender,
            address(this),
            value,
            deadline,
            v,
            r,
            s
        );
        (amountA, amountB) = removeLiquidity(
            tokenA,
            tokenB,
            liquidity,
            amountAMin,
            amountBMin,
            to,
            deadline
        );
    }

    function removeLiquidityETHWithPermit(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) public virtual override returns (uint256 amountToken, uint256 amountETH) {
        address pair = SecureLibrary.pairFor(factory, token, WETH);
        uint256 value = approveMax ? type(uint256).max : liquidity;
        ISecurePair(pair).permit(
            msg.sender,
            address(this),
            value,
            deadline,
            v,
            r,
            s
        );
        (amountToken, amountETH) = removeLiquidityETH(
            token,
            liquidity,
            amountTokenMin,
            amountETHMin,
            to,
            deadline
        );
    }

    function removeLiquidityETHWithPermitSupportingFeeOnTransferTokens(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external virtual override returns (uint256 amountETH) {
        address pair = SecureLibrary.pairFor(factory, token, WETH);
        uint256 value = approveMax ? type(uint256).max : liquidity;
        ISecurePair(pair).permit(
            msg.sender,
            address(this),
            value,
            deadline,
            v,
            r,
            s
        );
        amountETH = removeLiquidityETHSupportingFeeOnTransferTokens(
            token,
            liquidity,
            amountTokenMin,
            amountETHMin,
            to,
            deadline
        );
    }

    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        uint256 startline,
        uint256 deadline,
        bytes calldata signature
    )
        external
        virtual
        override
        ensureSwap(startline, deadline)
        returns (uint256[] memory amounts)
    {
        _verifySignature(
            amountIn,
            amountOutMin,
            path,
            startline,
            deadline,
            signature
        );

        amounts = SecureLibrary.getAmountsOut(factory, amountIn, path);
        if (amounts[amounts.length - 1] < amountOutMin) {
            revert RouterInsufficientOutputAmount();
        }
        TransferHelper.safeTransferFrom(
            path[0],
            msg.sender,
            SecureLibrary.pairFor(factory, path[0], path[1]),
            amounts[0]
        );
        _swap(amounts, path, msg.sender);
    }

    function swapTokensForExactTokens(
        uint256 amountOut,
        uint256 amountInMax,
        address[] calldata path,
        uint256 startline,
        uint256 deadline,
        bytes calldata signature
    )
        external
        virtual
        override
        ensureSwap(startline, deadline)
        returns (uint256[] memory amounts)
    {
        _verifySignature(
            amountInMax,
            amountOut,
            path,
            startline,
            deadline,
            signature
        );

        amounts = SecureLibrary.getAmountsIn(factory, amountOut, path);
        if (amounts[0] > amountInMax) {
            revert RouterExcessiveInputAmount();
        }
        TransferHelper.safeTransferFrom(
            path[0],
            msg.sender,
            SecureLibrary.pairFor(factory, path[0], path[1]),
            amounts[0]
        );
        _swap(amounts, path, msg.sender);
    }

    function swapExactETHForTokens(
        uint256 amountOutMin,
        address[] calldata path,
        uint256 startline,
        uint256 deadline,
        bytes calldata signature
    )
        external
        payable
        virtual
        override
        ensureSwap(startline, deadline)
        returns (uint256[] memory amounts)
    {
        if (path[0] != WETH) {
            revert RouterInvalidPath();
        }

        _verifySignature(
            msg.value,
            amountOutMin,
            path,
            startline,
            deadline,
            signature
        );

        amounts = SecureLibrary.getAmountsOut(factory, msg.value, path);
        if (amounts[amounts.length - 1] < amountOutMin) {
            revert RouterInsufficientOutputAmount();
        }
        IWETH(WETH).deposit{value: amounts[0]}();
        assert(
            IWETH(WETH).transfer(
                SecureLibrary.pairFor(factory, path[0], path[1]),
                amounts[0]
            )
        );
        _swap(amounts, path, msg.sender);
    }

    function swapTokensForExactETH(
        uint256 amountOut,
        uint256 amountInMax,
        address[] calldata path,
        uint256 startline,
        uint256 deadline,
        bytes calldata signature
    )
        external
        virtual
        override
        ensureSwap(startline, deadline)
        returns (uint256[] memory amounts)
    {
        if (path[path.length - 1] != WETH) {
            revert RouterInvalidPath();
        }
        _verifySignature(
            amountInMax,
            amountOut,
            path,
            startline,
            deadline,
            signature
        );

        amounts = SecureLibrary.getAmountsIn(factory, amountOut, path);
        if (amounts[0] > amountInMax) {
            revert RouterExcessiveInputAmount();
        }
        TransferHelper.safeTransferFrom(
            path[0],
            msg.sender,
            SecureLibrary.pairFor(factory, path[0], path[1]),
            amounts[0]
        );
        _swap(amounts, path, address(this));
        IWETH(WETH).withdraw(amounts[amounts.length - 1]);
        TransferHelper.safeTransferETH(msg.sender, amounts[amounts.length - 1]);
    }

    function swapExactTokensForETH(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        uint256 startline,
        uint256 deadline,
        bytes calldata signature
    )
        external
        virtual
        override
        ensureSwap(startline, deadline)
        returns (uint256[] memory amounts)
    {
        if (path[path.length - 1] != WETH) {
            revert RouterInvalidPath();
        }
        _verifySignature(
            amountIn,
            amountOutMin,
            path,
            startline,
            deadline,
            signature
        );

        amounts = SecureLibrary.getAmountsOut(factory, amountIn, path);

        if (amounts[amounts.length - 1] < amountOutMin) {
            revert RouterInsufficientOutputAmount();
        }
        TransferHelper.safeTransferFrom(
            path[0],
            msg.sender,
            SecureLibrary.pairFor(factory, path[0], path[1]),
            amounts[0]
        );
        _swap(amounts, path, address(this));
        IWETH(WETH).withdraw(amounts[amounts.length - 1]);
        TransferHelper.safeTransferETH(msg.sender, amounts[amounts.length - 1]);
    }

    function swapETHForExactTokens(
        uint256 amountOut,
        address[] calldata path,
        uint256 startline,
        uint256 deadline,
        bytes calldata signature
    )
        external
        payable
        virtual
        override
        ensureSwap(startline, deadline)
        returns (uint256[] memory amounts)
    {
        if (path[0] != WETH) {
            revert RouterInvalidPath();
        }
        _verifySignature(
            msg.value,
            amountOut,
            path,
            startline,
            deadline,
            signature
        );

        amounts = SecureLibrary.getAmountsIn(factory, amountOut, path);
        if (amounts[0] > msg.value) {
            revert RouterExcessiveInputAmount();
        }
