            abi.encodePacked(
                "\x19\x01",
                DOMAIN_SEPARATOR,
                keccak256(
                    abi.encode(
                        SWAP_TYPEHASH,
                        caller,
                        amountIn,
                        amountOut,
                        path,
                        nonceCaller,
                        startline,
                        deadline
                    )
